<?php declare(strict_types=1); namespace Tests\Unit\Approval; use App\Approval\ApprovalRequest; use App\Approval\ApprovalStatus; use PHPUnit\Framework\TestCase; class ApprovalRequestModelTest extends TestCase { /** @test */ public function approval_request_uses_tenant_connection(): void { $this->assertSame("tenant", (new ApprovalRequest())->getConnectionName()); } /** @test */ public function approval_request_uses_correct_table(): void { $this->assertSame("approval_requests", (new ApprovalRequest())->getTable()); } /** @test */ public function approval_status_enum_values_are_correct(): void { $this->assertSame("pending", ApprovalStatus::PENDING->value); $this->assertSame("approved", ApprovalStatus::APPROVED->value); $this->assertSame("rejected", ApprovalStatus::REJECTED->value); $this->assertSame("cancelled", ApprovalStatus::CANCELLED->value); } /** @test */ public function is_pending_returns_true_only_for_pending_status(): void { $m = new ApprovalRequest(); $m->status = ApprovalStatus::PENDING; $this->assertTrue($m->isPending()); $m->status = ApprovalStatus::APPROVED; $this->assertFalse($m->isPending()); $m->status = ApprovalStatus::REJECTED; $this->assertFalse($m->isPending()); $m->status = ApprovalStatus::CANCELLED; $this->assertFalse($m->isPending()); } /** @test */ public function is_terminal_returns_true_for_terminal_states(): void { $m = new ApprovalRequest(); $m->status = ApprovalStatus::PENDING; $this->assertFalse($m->isTerminal()); $m->status = ApprovalStatus::APPROVED; $this->assertTrue($m->isTerminal()); $m->status = ApprovalStatus::REJECTED; $this->assertTrue($m->isTerminal()); $m->status = ApprovalStatus::CANCELLED; $this->assertTrue($m->isTerminal()); } /** @test */ public function approval_request_has_required_fillable_fields(): void { $fillable = (new ApprovalRequest())->getFillable(); foreach (["approvable_type","approvable_id","requested_by","status","tenant_slug","notes"] as $f) { $this->assertContains($f, $fillable); } } /** @test */ public function approval_request_casts_status_to_enum(): void { $casts = (new ApprovalRequest())->getCasts(); $this->assertArrayHasKey("status", $casts); $this->assertSame(ApprovalStatus::class, $casts["status"]); } }